function removeFromEnd(head, n) {
  const dummy = { val: 0, next: head }
  let lead = dummy
  let trail = dummy
  for (let i = 0; i < n; i++) lead = lead.next
  while (lead.next !== null) {
    lead = lead.next
    trail = trail.next
  }
  trail.next = trail.next.next
  return dummy.next
}

