def remove_from_end(head, n):
    dummy = {"val": 0, "next": head}
    lead = trail = dummy
    for _ in range(n):
        lead = lead["next"]
    while lead["next"] is not None:
        lead = lead["next"]
        trail = trail["next"]
    trail["next"] = trail["next"]["next"]
    return dummy["next"]
